  `no_sr` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sales_invoice` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_invoice` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sr_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sr_date` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_recipient` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_address` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_telp` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_fax` int DEFAULT NULL,
  `shipping_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_bill` double DEFAULT NULL,
  `remaining_bill` double DEFAULT NULL,
  `assign_by` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assign_to` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assign_date` date DEFAULT NULL,
  `bill_status` smallint DEFAULT NULL,
  `validate_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tb_collect_idy_ppn_no_sr_unique` (`no_sr`)
