DROP TABLE IF EXISTS `tb_collect_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_collect_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `no_sr` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sr_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'tipe tagihan',
  `sr_date` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'tanggal tagihan dari bsi',
  `customer_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_recipient` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_address` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_telp` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_fax` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'alamat pengiriman',
  `total_bill` double DEFAULT NULL COMMENT 'total tagihan',
  `remaining_bill` double DEFAULT NULL COMMENT 'sisa tagihan',
  `assign_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'di assign oleh siapa',
  `assign_to` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'di assign ke siapa',
  `assign_date` date DEFAULT NULL COMMENT 'tanggal penagihan',
  `bill_status` int NOT NULL DEFAULT '0' COMMENT '0 => belum ditagih,\r\n1 => tagihan berjalan,\r\n2 => tagihan selesai,\r\n3 => tagihan tertunda',
  `validate_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'divalidasi oleh siapa',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tb_collect_tasks_no_sr_unique` (`no_sr`),
  KEY `assign_by` (`assign_by`),
  KEY `assign_to` (`assign_to`),
  KEY `no_sr` (`no_sr`),
  KEY `sr_type` (`sr_type`),
  KEY `customer_name` (`customer_name`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

